import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Orders from './pages/Orders';
import Suppliers from './pages/Suppliers';

function App() {
    const [customer, setCustomer] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Check if customer is already logged in
        const savedCustomer = localStorage.getItem('customer');
        if (savedCustomer) {
            try {
                setCustomer(JSON.parse(savedCustomer));
            } catch (error) {
                localStorage.removeItem('customer');
            }
        }
        setLoading(false);
    }, []);

    const handleLoginSuccess = (customerData) => {
        setCustomer(customerData);
    };

    const handleLogout = () => {
        localStorage.removeItem('customer');
        setCustomer(null);
    };

    if (loading) {
        return <div>Loading...</div>;
    }

    return (
        <Router>
            <Routes>
                <Route 
                    path="/login" 
                    element={
                        customer ? 
                        <Navigate to="/dashboard" /> : 
                        <Login onLoginSuccess={handleLoginSuccess} />
                    } 
                />
                <Route 
                    path="/dashboard" 
                    element={
                        customer ? 
                        <Dashboard customer={customer} onLogout={handleLogout} /> : 
                        <Navigate to="/login" />
                    } 
                />
                <Route 
                    path="/inventory" 
                    element={
                        customer ? 
                        <Inventory customer={customer} onLogout={handleLogout} /> : 
                        <Navigate to="/login" />
                    } 
                />
                <Route 
                    path="/orders" 
                    element={
                        customer ? 
                        <Orders customer={customer} onLogout={handleLogout} /> : 
                        <Navigate to="/login" />
                    } 
                />
                <Route 
                    path="/suppliers" 
                    element={
                        customer ? 
                        <Suppliers customer={customer} onLogout={handleLogout} /> : 
                        <Navigate to="/login" />
                    } 
                />
                <Route 
                    path="/" 
                    element={<Navigate to={customer ? "/dashboard" : "/login"} />} 
                />
            </Routes>
        </Router>
    );
}

export default App;
